// Beat-sync helpers — the spine of the film. Every visual hit is locked to an
// event in beatmap.json (generated by scripts/synth-music.py from the music
// track). This is what makes the video feel "10x": UI pops, text reveals, and
// transitions land EXACTLY on a kick/snare/stab, not on arbitrary timers.
import beatmapData from './beatmap.json';

export type BeatEvent = { kind: string; t: number; frame: number; label: string };
export const BEATMAP = beatmapData as {
  bpm: number;
  fps: number;
  beat: number;
  events: BeatEvent[];
};

export const MUSIC_FPS = BEATMAP.fps; // 60
export const MUSIC_BPM = BEATMAP.bpm; // 128
export const BEAT_SEC = BEATMAP.beat; // 0.46875s

// all events of a kind, in frame order
const byKind = (kind: string) =>
  BEATMAP.events.filter((e) => e.kind === kind).sort((a, b) => a.frame - b.frame);
export const KICKS = byKind('kick');
export const SNARES = byKind('snare');
export const STABS = byKind('stab');
export const TICKS = byKind('tick');

// nth event of a kind (1-indexed for readable call sites: kick(1) = first kick)
export const kick = (n: number) => KICKS[n - 1]?.frame ?? 0;
export const snare = (n: number) => SNARES[n - 1]?.frame ?? 0;
export const stab = (n: number) => STABS[n - 1]?.frame ?? 0;

// frame -> seconds helper at the composition fps
export const sec = (s: number, fps = MUSIC_FPS) => Math.round(s * fps);

// find the nearest beat-event frame <= `frame` of a given kind (for "is this
// frame on a kick?" checks). Returns distance in frames (0 = exactly on beat).
export const distToLast = (frame: number, events: BeatEvent[]) => {
  let lo = 0,
    hi = events.length - 1,
    ans = -1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    if (events[mid].frame <= frame) {
      ans = mid;
      lo = mid + 1;
    } else hi = mid - 1;
  }
  if (ans < 0) return Infinity;
  return frame - events[ans].frame;
};

// a "hit" envelope: 1.0 right on the beat, decaying over `decayFrames`.
// Use to pulse/glow UI elements with the kick.
export const hitPulse = (frame: number, events: BeatEvent[], decayFrames = 18) => {
  const d = distToLast(frame, events);
  if (d === Infinity || d > decayFrames) return 0;
  return Math.pow(1 - d / decayFrames, 2);
};

// spring-y "just appeared" progress for an element that should pop in on the
// nearest beat at or after `startFrame`. 0 -> 1 with an overshoot settle.
export const appearOn = (frame: number, beatFrame: number, fps = MUSIC_FPS) => {
  const local = frame - beatFrame;
  if (local < 0) return 0;
  // fast snap (8 frames) then settle — bezier feel via piecewise
  const rise = Math.min(1, local / 8);
  const ease = 1 - Math.pow(1 - rise, 3); // easeOutCubic
  // small overshoot at the top
  const overshoot = local < 14 ? Math.sin((local / 14) * Math.PI) * 0.08 : 0;
  return Math.max(0, Math.min(1.08, ease + overshoot));
};
